#include <iostream>
long memo[10] = {0};
long fib(int n) {
    if (n < 2) return n;
    if (memo[n]) return memo[n];
    return memo[n] = fib(n - 1) + fib(n - 2);
}
int main() { std::cout << fib(6); }

