#include <iostream>
long calls = 0;
long fib(int n) {
    calls++;
    if (n < 2) return n;
    return fib(n - 1) + fib(n - 2);
}
int main() { fib(5); std::cout << calls; }

#include <iostream>
int main() {
    int dp[6] = {};
    int w[] = {2, 3}, v[] = {3, 4};
    for (int i = 0; i < 2; i++)
        for (int c = 5; c >= w[i]; c--)
            if (v[i] + dp[c - w[i]] > dp[c]) dp[c] = v[i] + dp[c - w[i]];
    std::cout << dp[5];
}
